import java.util.ArrayList;
import java.util.List;

public class SignalBusTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        SignalBus bus = new SignalBus();
        List<String> log = new ArrayList<>();
        bus.on("save", p -> log.add("disk:" + p));
        bus.on("save", p -> log.add("audit:" + p));
        bus.on("quit", p -> log.add("bye:" + p));

        check("handlerCount(save)", 2, bus.handlerCount("save"));
        check("handlerCount on an unknown name", 0, bus.handlerCount("open"));
        check("emit(save) reports how many ran", 2, bus.emit("save", "doc"));
        check("handlers ran in registration order", "[disk:doc, audit:doc]", log.toString());
        check("emit on an unknown name", 0, bus.emit("open", "doc"));
        check("clear(save) reports removals", 2, bus.clear("save"));
        check("emit after clear", 0, bus.emit("save", "doc"));
        check("other names survive clear", 1, bus.emit("quit", "now"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

