import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

public class SignalBus {

    private final Map<String, List<Consumer<String>>> handlers = new HashMap<>();

    public void on(String name, Consumer<String> handler) {
        handlers.computeIfAbsent(name, key -> new ArrayList<>()).add(handler);
    }

    public int emit(String name, String payload) {
        List<Consumer<String>> forName = handlers.get(name);
        if (forName == null) {
            return 0;
        }
        for (Consumer<String> handler : forName) {
            handler.accept(payload);
        }
        return forName.size();
    }

    public int clear(String name) {
        List<Consumer<String>> removed = handlers.remove(name);
        return removed == null ? 0 : removed.size();
    }

    public int handlerCount(String name) {
        List<Consumer<String>> forName = handlers.get(name);
        return forName == null ? 0 : forName.size();
    }
}
